{"content": "1|// Code-Intel v2 / L2b — make clangd-derived LSP_VERIFIED edges VISIBLE and
2|// TRUSTWORTHY in the agent-facing verbs.
3|//
4|// Asserts:
5|//   (a) graph_callers marks the lsp-verified edge ([lsp✓]) AND emits the
6|//       `TRUST: lsp-verified (...)` banner naming the compile-db hash.
7|//   (b) a heuristic-only symbol emits the `TRUST: heuristic only (...)`
8|//       undercount caveat (and never the lsp banner).
9|//   (c) lsp-verified edges rank ABOVE heuristic ones (and are never the first
10|//       dropped under budget).
11|//
12|// Producer side (LSP_VERIFIED edges + code_intel_collections row) landed in
13|// L2a; this is the L2b consumer-surface test.
14|
15|import { describe, expect, it, beforeEach, afterEach } from 'vitest';
16|import { mkdtemp, rm } from 'node:fs/promises';
17|import { tmpdir } from 'node:os';
18|import { join } from 'node:path';
19|import { mkdirSync, writeFileSync } from 'node:fs';
20|import { execFileSync } from 'node:child_process';
21|import { openDb } from '../../../mcp/stdio/storage/db.js';
22|import { upsertNode } from '../../../mcp/stdio/storage/nodes.js';
23|import { upsertEdge } from '../../../mcp/stdio/storage/edges.js';
24|import { graphCallers } from '../../../mcp/stdio/query/verbs/callers.js';
25|import { graphCallees } from '../../../mcp/stdio/query/verbs/callees.js';
26|import { graphNeighbors } from '../../../mcp/stdio/query/verbs/neighbors.js';
27|import { graphImpact } from '../../../mcp/stdio/query/verbs/impact.js';
28|import { rankCallers } from '../../../mcp/stdio/query/rank.js';
29|import { enforceBudget } from '../../../mcp/stdio/query/budget.js';
30|
31|const COMPILE_DB_HASH = 'deadbeefcafef00d';
32|
33|describe('Code-Intel v2 L2b — LSP_VERIFIED surface', () => {
34|  let repoRoot;
35|  let head;
36|
37|  beforeEach(async () => {
38|    repoRoot = await mkdtemp(join(tmpdir(), 'apg-lsp-surface-'));
39|    const run = (...args) => execFileSync('git', ['-C', repoRoot, ...args], { stdio: 'ignore' });
40|    run('init', '-q');
41|    run('-c', 'user.email=t@t', '-c', 'user.name=t', 'commit', '--allow-empty', '-m', 'init');
42|    head = execFileSync('git', ['-C', repoRoot, 'rev-parse', 'HEAD'], { encoding: 'utf8' }).trim();
43|
44|    mkdirSync(join(repoRoot, '.aify-graph'), { recursive: true });
45|    writeFileSync(join(repoRoot, '.aify-graph', 'manifest.json'), JSON.stringify({
46|      commit: head, indexedAt: new Date().toISOString(),
47|      nodes: 0, edges: 0,
48|      schemaVersion: 4, extractorVersion: '0.1.0',
49|      status: 'ok', dirtyFiles: [], dirtyEdges: [], dirtyEdgeCount: 0,
50|    }));
51|
52|    const db = openDb(join(repoRoot, '.aify-graph', 'graph.sqlite'));
53|    try {
54|      const node = (id, label, file_path) => ({
55|        id, type: 'Function', label, file_path,
56|        start_line: 1, end_line: 1, language: 'cpp', confidence: 1,
57|        structural_fp: '', dependency_fp: '', extra: {},
58|      });
59|      // Symbol WITH lsp-verified evidence: `RenderPass::execute` has one
60|      // clangd-verified caller and one heuristic caller.
61|      upsertNode(db, node('fn:lspVerifiedCaller', 'DispatchFrame', 'src/dispatch.cpp'));
62|      upsertNode(db, node('fn:heuristicCaller', 'maybeCaller', 'src/guess.cpp'));
63|      upsertNode(db, node('fn:target', 'execute', 'src/renderpass.cpp'));
64|
65|      upsertEdge(db, {
66|        from_id: 'fn:lspVerifiedCaller', to_id: 'fn:target', relation: 'CALLS',
67|        source_file: 'src/dispatch.cpp', source_line: 42, confidence: 0.5,
68|        provenance: 'LSP_VERIFIED', extractor: `cpp-clangd#${COMPILE_DB_HASH.slice(0, 8)}`,
69|      });
70|      upsertEdge(db, {
71|        from_id: 'fn:heuristicCaller', to_id: 'fn:target', relation: 'CALLS',
72|        source_file: 'src/guess.cpp', source_line: 7, confidence: 0.99,
73|        provenance: 'INFERRED', extractor: 'cpp',
74|      });
75|
76|      // ALL-VERIFIED symbol: `cleanExecute` has a single clangd-verified caller
77|      // and NO heuristic edges — the only shape that may earn the index-ready
78|      // "exhaustive" attestation (audit 2026-06-12 B4).
79|      upsertNode(db, node('fn:cleanCaller', 'CleanDispatch', 'src/clean.cpp'));
80|      upsertNode(db, node('fn:cleanTarget', 'cleanExecute', 'src/cleanpass.cpp'));
81|      upsertEdge(db, {
82|        from_id: 'fn:cleanCaller', to_id: 'fn:cleanTarget', relation: 'CALLS',
83|        source_file: 'src/clean.cpp', source_line: 11, confidence: 0.5,
84|        provenance: 'LSP_VERIFIED', extractor: `cpp-clangd#${COMPILE_DB_HASH.slice(0, 8)}`,
85|      });
86|
87|      // Heuristic-ONLY symbol: `parseConfig` has a single INFERRED caller and
88|      // no clangd evidence at all.
89|      upsertNode(db, node('fn:plainCaller', 'bootstrap', 'src/boot.cpp'));
90|      upsertNode(db, node('fn:plainTarget', 'parseConfig', 'src/config.cpp'));
91|      upsertEdge(db, {
92|        from_id: 'fn:plainCaller', to_id: 'fn:plainTarget', relation: 'CALLS',
93|        source_file: 'src/boot.cpp', source_line: 3, confidence: 0.8,
94|        provenance: 'INFERRED', extractor: 'cpp',
95|      });
96|
97|      // Heuristic-only ISOLATED symbol: a node with NO edges at all, so the
98|      // traversal verbs hit their empty-result/absence path (I1).
99|      upsertNode(db, node('fn:islandTarget', 'isolatedFn', 'src/island.cpp'));
100|
101|      // A fresh clangd collection row vouching for the LSP_VERIFIED edge.
102|      db.run(
103|        `INSERT INTO code_intel_collections
104|           (collection_id, provider, provider_version, project_root, language, status,
105|            freshness_basis, freshness_value, compile_db_hash, indexed_commit,
106|            operations_json, collected_at, errors_json)
107|         VALUES ($id, $provider, $pv, $root, $lang, $status,
108|            $fb, $fv, $hash, $commit, $ops, $at, NULL)`,
109|        {
110|          id: 'ci-1', provider: 'cpp-clangd', pv: '0.1.0', root: repoRoot, lang: 'cpp',
111|          status: 'ok', fb: 'compile_db_hash', fv: COMPILE_DB_HASH, hash: COMPILE_DB_HASH,
112|          commit: head, ops: JSON.stringify({ calls: { status: 'ok', count: 1 } }),
113|          at: new Date().toISOString(),
114|        },
115|      );
116|    } finally {
117|      db.close();
118|    }
119|  });
120|
121|  afterEach(async () => {
122|    if (repoRoot) {
123|      try { await rm(repoRoot, { recursive: true, force: true }); } catch {}
124|    }
125|  });
126|
127|  it('(a) marks the lsp edge and shows the lsp-verified TRUST line', async () => {
128|    const out = await graphCallers({ repoRoot, symbol: 'execute' });
129|    expect(typeof out).toBe('string');
130|    // Edge marker: clangd ground truth is tagged distinctly.
131|    expect(out).toContain('[lsp✓]');
132|    // TRUST banner names the provider + compile-db hash (8 chars).
133|    expect(out).toMatch(/TRUST: lsp-verified \(cpp-clangd, compile-db deadbeef, collected /);
134|    // Fresh collection (HEAD == indexed_commit, hash matches) → NOT stale.
135|    expect(out).not.toContain('STALE');
136|    // It must NOT fall back to the heuristic-only caveat.
137|    expect(out).not.toContain('heuristic only');
138|  });
139|
140|  it('(b) heuristic-only symbol shows the undercount caveat, not the lsp line', async () => {
141|    const out = await graphCallers({ repoRoot, symbol: 'parseConfig' });
142|    expect(typeof out).toBe('string');
143|    expect(out).toContain('TRUST: heuristic only (tree-sitter)');
144|    expect(out).toContain('graph_collect_code_intel');
145|    expect(out).not.toContain('[lsp✓]');
146|    expect(out).not.toContain('lsp-verified');
147|  });
148|
149|  it('(d) FIX A/B: indexReady=true + ALL-verified result → "index-ready, N callers" attestation', async () => {
