81|      for (let i = 0; i < 2; i += 1) {
82|        upsertNode(db, node(`fn:v${i}`, `real_caller_${i}`, 'src/app.py'));
83|        upsertEdge(db, {
84|          from_id: `fn:v${i}`, to_id: 'fn:target', relation: 'CALLS',
85|          source_file: 'src/app.py', source_line: 100 + i, confidence: 0.95,
86|          provenance: 'LSP_VERIFIED', extractor: 'pyright#1',
87|        });
88|      }
