98|      expect(provenanceRank('LSP_VERIFIED')).toBeGreaterThan(provenanceRank('EXTRACTED'));
99|      expect(provenanceRank('EXTRACTED')).toBeGreaterThan(provenanceRank('AMBIGUOUS'));
