104|      // The fail-closed direction. A provenance this build has never heard of must not be promoted
105|      // above evidence we can vouch for — that would let a future tag manufacture trust silently.
106|      expect(provenanceRank('SOMETHING_NEW')).toBe(0);
107|      expect(provenanceRank(undefined)).toBe(0);
108|      expect(provenanceRank('SOMETHING_NEW')).toBeLessThan(provenanceRank('AMBIGUOUS'));
109|    });
