114|      const sql = provenanceRankSql('e.provenance');
115|      for (const p of ['LSP_VERIFIED', 'EXTRACTED', 'INFERRED', 'AMBIGUOUS']) {
116|        expect(sql).toContain(`'${p}' THEN ${provenanceRank(p)}`);
117|      }
118|      expect(sql).toContain('ELSE 0');
119|    });
120|
