122|      // The expression is string-interpolated into SQL, so the guard is the only thing between it
123|      // and an injection if a call site ever passes a value instead of a literal.
124|      expect(() => provenanceRankSql('provenance')).not.toThrow();
125|      expect(() => provenanceRankSql('e.provenance')).not.toThrow();
126|      expect(() => provenanceRankSql('e.provenance; DROP TABLE nodes')).toThrow();
127|      expect(() => provenanceRankSql('(SELECT 1)')).toThrow();
128|      expect(() => provenanceRankSql('')).toThrow();
129|    });
130|  });
131|
132|  describe('graph_preflight — the verb that answers "is this safe to change"', () => {
133|    it('⛔ shows the VERIFIED callers, not the higher-confidence heuristic ones', async () => {
134|      const out = await graphPreflight({ repoRoot, symbol: 'target' });
135|      const shown = String(out).split('\n').filter((l) => /conf=/.test(l));
136|
137|      expect(shown.length).toBeGreaterThan(0);
138|      // Both verified callers must appear despite carrying the LOWER confidence.
139|      expect(shown.filter((l) => /real_caller_/.test(l))).toHaveLength(2);
140|      // And they must lead — a reader who stops after the first line still sees the best evidence.
141|      expect(shown[0]).toMatch(/real_caller_/);
142|    });
143|
144|    it('⛔ TAGS the tier — the row already carried provenance and the render dropped it', async () => {
145|      const out = await graphPreflight({ repoRoot, symbol: 'target' });
146|      const shown = String(out).split('\n').filter((l) => /conf=/.test(l));
147|
148|      // Verified lines are marked, so an agent can tell ground truth from a guess at a glance.
149|      for (const l of shown.filter((x) => /real_caller_/.test(x))) expect(l).toMatch(/\[lsp/);
150|      // Heuristic lines are marked as heuristic — not silently equal to the verified ones.
151|      for (const l of shown.filter((x) => /test_heuristic_/.test(x))) expect(l).toMatch(/prov=AMBIGUOUS/);
152|    });
